@Test
public void testTouchDir() throws Exception {
  // Ensure newDir does not exist
  final String newDirName = "newDir";
  final Path newDir = new Path(newDirName);
  lfs.delete(newDir, true);
  assertThat(lfs.exists(newDir)).isFalse();

  {
    // -c must not create anything for a non-existent path.
    assertThat(shellRun("-touch", "-c", newDirName))
        .as("Expected successful touch on a non-existent path" +
            " with -c option")
        .isEqualTo(0);
    assertThat(lfs.exists(newDir)).isFalse();
  }

  lfs.mkdirs(newDir);
  assertThat(lfs.getFileStatus(newDir).isDirectory()).isTrue();

  {
    // Touching a directory must succeed without creating anything inside it.
    assertThat(shellRun("-touch", newDirName))
        .as("Expected successful touch on a directory").isEqualTo(0);
    assertThat(lfs.getFileStatus(newDir).isDirectory()).isTrue();
    assertThat(lfs.listStatus(newDir)).isEmpty();
  }

  {
    String strTime = formatTimestamp(System.currentTimeMillis());
    Date dateObj = parseTimestamp(strTime);

    assertThat(shellRun("-touch", "-t", strTime, newDirName))
        .as("Expected successful touch on a directory" +
            " with a specified timestamp")
        .isEqualTo(0);
    FileStatus newStatus = lfs.getFileStatus(newDir);
    assertThat(newStatus.getAccessTime()).isEqualTo(dateObj.getTime());
    assertThat(newStatus.getModificationTime()).isEqualTo(dateObj.getTime());
  }

  FileStatus fstatus = lfs.getFileStatus(newDir);

  {
    String strTime = formatTimestamp(System.currentTimeMillis() + 60000L);
    Date dateObj = parseTimestamp(strTime);

    assertThat(shellRun("-touch", "-a", "-t", strTime, newDirName))
        .as("Expected successful touch on a directory" +
            " with a specified access time")
        .isEqualTo(0);
    // Verify if access time is recorded correctly (and modification time
    // remains unchanged).
    FileStatus newStatus = lfs.getFileStatus(newDir);
    assertThat(newStatus.getAccessTime()).isEqualTo(dateObj.getTime());
    assertThat(newStatus.getModificationTime())
        .isEqualTo(fstatus.getModificationTime());
  }

  fstatus = lfs.getFileStatus(newDir);

  {
    String strTime = formatTimestamp(System.currentTimeMillis() + 120000L);
    Date dateObj = parseTimestamp(strTime);

    assertThat(shellRun("-touch", "-m", "-t", strTime, newDirName))
        .as("Expected successful touch on a directory" +
            " with a specified modification time")
        .isEqualTo(0);
    // Verify if modification time is recorded correctly (and access time
    // remains unchanged).
    FileStatus newStatus = lfs.getFileStatus(newDir);
    assertThat(newStatus.getAccessTime())
        .isEqualTo(fstatus.getAccessTime());
    assertThat(newStatus.getModificationTime())
        .isEqualTo(dateObj.getTime());
  }

  {
    // -c on an existing directory must still update the timestamps.
    String strTime = formatTimestamp(System.currentTimeMillis() + 180000L);
    Date dateObj = parseTimestamp(strTime);

    assertThat(shellRun("-touch", "-c", "-t", strTime, newDirName))
        .as("Expected successful touch on an existing directory" +
            " with -c option")
        .isEqualTo(0);
    FileStatus newStatus = lfs.getFileStatus(newDir);
    assertThat(newStatus.getAccessTime()).isEqualTo(dateObj.getTime());
    assertThat(newStatus.getModificationTime()).isEqualTo(dateObj.getTime());
  }

  lfs.delete(newDir, true);
}

